namespace Tga.Domain;

public abstract class Entity { public Guid Id { get; set; } = Guid.NewGuid(); public DateTime CreatedUtc { get; set; } = DateTime.UtcNow; }
public abstract class VersionedEntity : Entity { public Guid Version { get; set; } = Guid.NewGuid(); }
public enum MembershipStatus { Pending, Active, Expiring, Expired, Suspended, Cancelled, Rejected }
public enum DocumentStatus { Uploaded, PendingReview, Approved, Rejected, Expired, Replaced }
public enum PaymentStatus { Created, Pending, Paid, Failed, Cancelled, Refunded, PartiallyRefunded }
public enum AttemptStatus { InProgress, Submitted, Passed, Failed, Abandoned }
public enum QuestionType { SingleChoice, MultipleChoice, TrueFalse }
public class MemberProfile : VersionedEntity {
 public string UserId { get; set; } = ""; public string MembershipNumber { get; set; } = "";
 public string FirstName { get; set; } = ""; public string LastName { get; set; } = ""; public string PreferredName { get; set; } = "";
 public string Email { get; set; } = ""; public string MobileNumber { get; set; } = ""; public DateTime? DateOfBirth { get; set; }
 public string IdentifierPlaceholder { get; set; } = ""; public string Address { get; set; } = ""; public string City { get; set; } = "";
 public string Province { get; set; } = ""; public string PostalCode { get; set; } = ""; public string ProfileStatus { get; set; } = "Pending";
 public DateTime UpdatedUtc { get; set; } public DateTime? LastReviewedUtc { get; set; }
}
public class MembershipPlan : Entity { public string Name { get; set; } = ""; public string Description { get; set; } = ""; public decimal JoiningFee { get; set; } public decimal AnnualFee { get; set; } public bool IsActive { get; set; } = true; public int DurationMonths { get; set; } = 12; }
public class Membership : VersionedEntity {
 public Guid MemberId { get; set; } public MemberProfile Member { get; set; } = null!; public Guid MembershipPlanId { get; set; } public MembershipPlan Plan { get; set; } = null!;
 public DateTime? StartDate { get; set; } public DateTime? EndDate { get; set; } public MembershipStatus Status { get; set; }
 public string RenewalStatus { get; set; } = "NotRequested"; public bool AutoRenewEnabled { get; set; } public Guid? LastPaymentId { get; set; } public DateTime UpdatedUtc { get; set; }
}
public class MembershipApplication : VersionedEntity { public Guid MemberId { get; set; } public Guid MembershipPlanId { get; set; } public string Status { get; set; } = "Pending"; public DateTime SubmittedUtc { get; set; } public DateTime? ReviewedUtc { get; set; } public string? ReviewedByUserId { get; set; } public string? RejectionReason { get; set; } public string? Notes { get; set; } }
public class MembershipStatusHistory : Entity { public Guid MembershipId { get; set; } public MembershipStatus PreviousStatus { get; set; } public MembershipStatus NewStatus { get; set; } public string ChangedBy { get; set; } = ""; public string Reason { get; set; } = ""; public DateTime ChangedUtc { get; set; } }
public class DocumentType : Entity { public string Name { get; set; } = ""; public string Description { get; set; } = ""; public bool IsRequired { get; set; } public bool RequiresExpiryDate { get; set; } public string AllowedMimeTypes { get; set; } = "application/pdf,image/jpeg,image/png"; public long MaxSizeBytes { get; set; } = 5242880; public bool IsActive { get; set; } = true; }
public class MemberDocument : VersionedEntity { public Guid MemberId { get; set; } public MemberProfile Member { get; set; } = null!; public Guid DocumentTypeId { get; set; } public DocumentType Type { get; set; } = null!; public string OriginalFileName { get; set; } = ""; public string StorageKey { get; set; } = ""; public string MimeType { get; set; } = ""; public long SizeBytes { get; set; } public string Checksum { get; set; } = ""; public string StorageProvider { get; set; } = "Demo"; public DocumentStatus Status { get; set; } = DocumentStatus.PendingReview; public DateTime UploadedUtc { get; set; } public DateTime? ReviewedUtc { get; set; } public string? ReviewedBy { get; set; } public string? RejectionReason { get; set; } public DateTime? ExpiryDate { get; set; } public bool IsDeleted { get; set; } }
public class DocumentReviewHistory : Entity { public Guid MemberDocumentId { get; set; } public DocumentStatus PreviousStatus { get; set; } public DocumentStatus NewStatus { get; set; } public string ReviewedBy { get; set; } = ""; public string Notes { get; set; } = ""; }
public class Assessment : VersionedEntity { public string Title { get; set; } = ""; public string Description { get; set; } = ""; public string Instructions { get; set; } = "Demo only; non-accredited."; public decimal PassPercentage { get; set; } = 80; public int? TimeLimitMinutes { get; set; } public int? MaxAttempts { get; set; } = 3; public bool RandomizeQuestions { get; set; } public bool IsActive { get; set; } = true; public bool IsAccredited { get; set; } public DateTime UpdatedUtc { get; set; } public List<Question> Questions { get; set; } = []; }
public class Question : Entity { public Guid AssessmentId { get; set; } public string QuestionText { get; set; } = ""; public QuestionType QuestionType { get; set; } public int Points { get; set; } = 1; public int SortOrder { get; set; } public bool IsActive { get; set; } = true; public List<QuestionOption> Options { get; set; } = []; }
