public class AssessmentAttempt : VersionedEntity { public Guid AssessmentId { get; set; } public Assessment Assessment { get; set; } = null!; public Guid MemberId { get; set; } public MemberProfile Member { get; set; } = null!; public DateTime StartedUtc { get; set; } public DateTime? SubmittedUtc { get; set; } public int Score { get; set; } public decimal Percentage { get; set; } public bool Passed { get; set; } public AttemptStatus Status { get; set; } public string QuestionSnapshotJson { get; set; } = "[]"; public decimal PassPercentage { get; set; } public int? TimeLimitMinutes { get; set; } public List<AssessmentAnswer> Answers { get; set; } = []; }
public class AssessmentAnswer : Entity { public Guid AttemptId { get; set; } public Guid QuestionId { get; set; } public string SelectedAnswer { get; set; } = "[]"; public int AwardedPoints { get; set; } }
public class Certificate : Entity { public Guid MemberId { get; set; } public Guid AssessmentAttemptId { get; set; } public string CertificateNumber { get; set; } = ""; public DateTime IssuedUtc { get; set; } public DateTime? ExpiresUtc { get; set; } public string CertificateType { get; set; } = "Demo / non-accredited"; public string Status { get; set; } = "Issued"; }
public class PaymentTransaction : VersionedEntity { public Guid MemberId { get; set; } public MemberProfile Member { get; set; } = null!; public Guid? MembershipId { get; set; } public string PaymentType { get; set; } = "AnnualMembership"; public string Provider { get; set; } = "Mock"; public string? ProviderReference { get; set; } public string MerchantReference { get; set; } = Guid.NewGuid().ToString("N"); public decimal Amount { get; set; } public string Currency { get; set; } = "ZAR"; public PaymentStatus Status { get; set; } public DateTime? PaidUtc { get; set; } public DateTime? FailedUtc { get; set; } public string? FailureReason { get; set; } }
public class PaymentWebhookEvent : Entity { public string Provider { get; set; } = ""; public string ProviderEventId { get; set; } = ""; public string PayloadHash { get; set; } = ""; public DateTime ReceivedUtc { get; set; } public DateTime? ProcessedUtc { get; set; } public string ProcessingStatus { get; set; } = "Received"; }
public class Refund : VersionedEntity { public Guid PaymentTransactionId { get; set; } public decimal Amount { get; set; } public string Reason { get; set; } = ""; public string Status { get; set; } = "Requested"; public string RequestedBy { get; set; } = ""; public string? ApprovedBy { get; set; } public string? ProviderReference { get; set; } public DateTime? CompletedUtc { get; set; } }
